//! String values (slice1/value.rs): JS `===`, `+`, `ToString` and
//! truthiness, directly and through the ported scheduler. The op programs
//! of docs/strings-fuzz/tools/unit-programs.json run on the slice-1 driver
//! and must give Solid's traces (fixtures/strings-units.json, regenerated by
//! docs/strings-fuzz/tools/unit-expectations.mjs).
use rust_solid::slice1::{from_json, BodyFn, Key, Out, Runtime, Value, ValueEffectFn};
use serde_json::{json, Value as J};
use std::{
    cell::RefCell,
    io::Write,
    process::{Command, Stdio},
    rc::Rc,
};

fn driver(ops: &J) -> J {
    let mut child = Command::new(env!("CARGO_BIN_EXE_slice1-driver"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    writeln!(child.stdin.take().unwrap(), "{ops}").unwrap();
    let out = child.wait_with_output().unwrap();
    serde_json::from_slice(&out.stdout).unwrap()
}

fn unit(name: &str) {
    let all: J = serde_json::from_str(include_str!("fixtures/strings-units.json")).unwrap();
    let case = &all[name];
    assert!(case.is_object(), "{name} is a unit program");
    assert_eq!(driver(&case["ops"]), case["expected"], "{name}");
}

#[test]
fn js_semantics_of_string_values() {
    let s = |x: &str| Value::str(x);
    // `===` by content; never equal to a number.
    assert_eq!(s("ab"), s("ab"));
    assert_ne!(s("1"), Value::Int(1));
    // `+`: concatenation when either side is a string, ToString of integers.
    assert_eq!(s("#").js_add(&Value::Int(-3)), Some(s("#-3")));
    assert_eq!(Value::Int(3).js_add(&s("")), Some(s("3")));
    assert_eq!(Value::Int(3).js_add(&Value::Int(4)), Some(Value::Int(7)));
    assert_eq!(Value::Bool(true).js_add(&s("x")), Some(s("truex")));
    assert_eq!(Value::Undef.js_add(&Value::Int(1)), None, "NaN is refused");
    assert_eq!(
        s("a").js_add(&from_json(&json!([1]))),
        None,
        "ToPrimitive is refused"
    );
    // Truthiness: "" is the only falsy string.
    assert!(!s("").truthy());
    assert!(s("0").truthy() && s(" ").truthy());
    // ToString, typeof, length and indexing in UTF-16 code units.
    assert_eq!(Value::Int(-10).to_js_string().as_deref(), Some("-10"));
    assert_eq!(s("x").type_of(), "string");
    assert_eq!(
        Value::str_get("é😀", &Key::name("length")),
        Some(Value::Int(3))
    );
    assert_eq!(Value::str_get("ab", &Key::Idx(1)), Some(s("b")));
    assert_eq!(Value::str_get("ab", &Key::Idx(2)), None);
    // JSON strings are string values.
    assert_eq!(from_json(&json!("me")), s("me"));
}

#[test]
fn an_equal_string_write_is_no_change() {
    let mut rt = Runtime::default();
    let sig = rt.signal_value(Value::str("ab"));
    let runs = Rc::new(RefCell::new(vec![]));
    let compute: BodyFn = Rc::new(move |rt: &mut Runtime, _| {
        let v = rt.read_value(sig)?;
        Ok(Out::Value(v.js_add(&Value::str("!")).unwrap()))
    });
    let seen = runs.clone();
    let apply: ValueEffectFn = Rc::new(move |_rt: &mut Runtime, v: Value, _p: Value| {
        seen.borrow_mut().push(v);
        None
    });
    rt.effect_with(
        compute,
        apply,
        None,
        rust_solid::slice1::EFFECT_RENDER,
        false,
    );
    rt.write_value(sig, Value::str("ab"));
    rt.flush();
    rt.write_value(sig, Value::str("b"));
    rt.flush();
    assert_eq!(*runs.borrow(), vec![Value::str("ab!"), Value::str("b!")]);
}

#[test]
fn equal_string_writes_through_the_driver() {
    unit("equal_string_write");
}
#[test]
fn concatenation_and_truthiness() {
    unit("coercions");
}
#[test]
fn string_lists_by_value_index_and_key() {
    unit("string_list");
}
